  test("unknown handler strict", () => {
    const unknown = (flag: string) => {
      throw new Error(`unknown ${flag}`);
    };
    expect(() => mri(["--unknown", "val"], { unknown })).toThrow();
  });

  test("alias defaults preserve string type", () => {
